const entrada = $input.first().json;

const nome = String(entrada.nome ?? entrada.Nome ?? '').trim();
const telefoneOriginal = String(entrada.telefone ?? entrada.Telefone ?? '').trim();
const telefone = telefoneOriginal.replace(/\D/g, '');
const servico = String(entrada.servico ?? entrada['Serviço desejado'] ?? '').trim();
const origem = String(entrada.origem ?? entrada['Origem do lead'] ?? '').trim();

const erros = [];
if (nome.length < 2) erros.push('nome inválido');
if (!/^\d{10,13}$/.test(telefone)) erros.push('telefone deve ter entre 10 e 13 dígitos');
if (!servico) erros.push('serviço desejado não informado');
if (!origem) erros.push('origem do lead não informada');

if (erros.length) {
  throw new Error(`DADOS_INVALIDOS: ${erros.join('; ')}`);
}

const formatar = (data) => new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  dateStyle: 'short',
  timeStyle: 'short',
}).format(data);

const agora = new Date();
const acompanhamento = new Date(agora.getTime() + 24 * 60 * 60 * 1000);

return [{
  json: {
    nome,
    telefone,
    servico,
    origem,
    data: formatar(agora),
    status: 'Pendente',
    responsavel: 'João',
    proximoAcompanhamento: formatar(acompanhamento),
  },
}];

const lead = $('Validar e preparar').first().json;
const linhas = $input.all().map((item) => item.json);
const normalizarTelefone = (valor) => String(valor ?? '').replace(/\D/g, '');

const duplicado = linhas.some((linha) => {
  const existente = normalizarTelefone(linha.Telefone ?? linha.telefone);
  return existente !== '' && existente === lead.telefone;
});

return [{
  json: {
    ...lead,
    duplicado,
    motivoDuplicidade: duplicado ? 'Telefone já cadastrado na planilha' : '',
  },
}];

const lead = $input.first().json;

return [{
  json: {
    'Nome': lead.nome,
    'Telefone': lead.telefone,
    'Serviço desejado': lead.servico,
    'Origem do lead': lead.origem,
    'Data': lead.data,
    'Status': lead.status,
    'Responsável': lead.responsavel,
    'Próximo acompanhamento': lead.proximoAcompanhamento,
  },
}];

const linhas = $input.all()
  .map((item) => item.json)
  .filter((linha) => Object.keys(linha).length > 0);

const normalizar = (valor) => String(valor ?? '').trim().toLocaleLowerCase('pt-BR');
const escaparHtml = (valor) => String(valor ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#039;');

const pendentes = linhas.filter((linha) => {
  const status = normalizar(linha.Status ?? linha.status);
  return ['pendente', 'novo', 'em andamento', 'aguardando'].includes(status);
});

const corpoTabela = pendentes.length
  ? pendentes.map((linha) => `
      <tr>
        <td>${escaparHtml(linha.Nome)}</td>
        <td>${escaparHtml(linha.Telefone)}</td>
        <td>${escaparHtml(linha['Serviço desejado'])}</td>
        <td>${escaparHtml(linha.Responsável)}</td>
        <td>${escaparHtml(linha['Próximo acompanhamento'])}</td>
      </tr>`).join('')
  : '<tr><td colspan="5">Nenhum lead pendente.</td></tr>';

const html = `
  <h2>Relatório diário de leads pendentes</h2>
  <p><strong>Total pendente:</strong> ${pendentes.length}</p>
  <table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse">
    <thead>
      <tr><th>Nome</th><th>Telefone</th><th>Serviço</th><th>Responsável</th><th>Próximo acompanhamento</th></tr>
    </thead>
    <tbody>${corpoTabela}</tbody>
  </table>`;

return [{
  json: {
    totalPendentes: pendentes.length,
    assunto: `Relatório diário: ${pendentes.length} lead(s) pendente(s)`,
    html,
  },
}];
